def finish(o, m, sub=2, smooth=True):
    for c in o.users_collection: c.objects.unlink(o)
    C.objects.link(o); o.parent = root
    o.data.materials.clear(); o.data.materials.append(M[m])
    if sub:
        md = o.modifiers.new("Subsurf", "SUBSURF"); md.levels = sub; md.render_levels = sub
    if smooth:
        for p in o.data.polygons: p.use_smooth = True
    return o

def ell(name, loc, dims, m, rot=(0, 0, 0), sub=1):
    bpy.ops.mesh.primitive_uv_sphere_add(segments=24, ring_count=12, radius=0.5, location=loc, rotation=[math.radians(r) for r in rot])
    o = bpy.context.active_object; o.name = name; o.scale = dims
    return finish(o, m, sub)

def box(name, loc, dims, m, rot=(0, 0, 0), sub=2, taper=None):
    bpy.ops.mesh.primitive_cube_add(size=1, location=loc, rotation=[math.radians(r) for r in rot])
    o = bpy.context.active_object; o.name = name; o.scale = dims
    if taper:   # taper=(sx_fundo, sy_fundo): estreita a face de baixo
        for v in o.data.vertices:
            if v.co.z < 0: v.co.x *= taper[0]; v.co.y *= taper[1]
    return finish(o, m, sub)

def limb(name, a, b, r, m, r2=None):
    a, b = Vector(a), Vector(b); d = b - a
    bpy.ops.mesh.primitive_cylinder_add(vertices=16, radius=r, depth=d.length, location=(a + b) / 2)
    o = bpy.context.active_object; o.name = name
    o.rotation_mode = "QUATERNION"; o.rotation_quaternion = d.to_track_quat("Z", "Y")
    if r2:
        for v in o.data.vertices:
            if v.co.z < 0: v.co.x *= r2 / r; v.co.y *= r2 / r
    return finish(o, m, 1)

