# --- Referencias (so visiveis em vista ortografica)
R = get_coll(REFC)
def ref(name, file, loc, rot):
    img = bpy.data.images.load(os.path.join(DIR, file), check_existing=True)
    e = bpy.data.objects.new(name, None); R.objects.link(e)
    e.empty_display_type = "IMAGE"; e.data = img
    e.empty_display_size = 730 * S
    e.location = loc; e.rotation_euler = [math.radians(r) for r in rot]
    e.use_empty_image_alpha = True; e.color[3] = 0.5
    e.show_empty_image_perspective = False
    e.hide_select = True
    return e
ref("REF_frente", "vince_ref_frente.jpg", (3 * S, 0.6, (728 - 385) * S), (90, 0, 0))
ref("REF_perfil", "vince_ref_perfil.jpg", (-0.6, -7 * S, (728 - 385) * S), (90, 0, -90))

