def light(name, kind, loc, rot, col, energy, size=1.0):
    lo = bpy.data.objects.get(name)
    if lo: bpy.data.objects.remove(lo, do_unlink=True)
    ld = bpy.data.lights.new(name, kind); ld.color = col; ld.energy = energy
    if kind == "AREA": ld.size = size
    lo = bpy.data.objects.new(name, ld); C.objects.link(lo)
    lo.location = loc; lo.rotation_euler = [math.radians(r) for r in rot]
